import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import test from "node:test";
import Ajv2020 from "ajv/dist/2020.js";

const schema = JSON.parse(await readFile("contracts/faux/script.schema.json", "utf8"));
const script = JSON.parse(await readFile("contracts/faux/minimal-script.json", "utf8"));
const validate = new Ajv2020({ allErrors: true, strict: true });

await test("the deterministic faux script satisfies its versioned schema", () => {
  assert.equal(validate.validate(schema, script), true, JSON.stringify(validate.errors));
});

await test("the faux schema rejects unknown provider steps", () => {
  const invalid = structuredClone(script);
  invalid.steps.push({ type: "network" });
  assert.equal(validate.validate(schema, invalid), false);
});
